import * as React from "react";

export type CameraIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CameraIcon({ size = 20, ...props }: CameraIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="7" width="17" height="12" rx="2" /><circle cx="12" cy="13" r="3.5" /><path d="M8.5 7 10 4.5h4L15.5 7" />
    </svg>
  );
}
